-- Control plane tables (docs/DISENO-PRODUCTO.md, "Modelo de dominio").
-- Becomes migration 0003 once the migration runner (U2) and project_id rename (U3) land.
-- Portability rules: standard SQL, ISO UTC text timestamps, text ids generated by the
-- application, no AUTOINCREMENT. audit_log.seq is the one integer key: in Postgres it
-- becomes GENERATED ALWAYS AS IDENTITY.

CREATE TABLE person (
    id TEXT PRIMARY KEY,
    google_sub TEXT NOT NULL UNIQUE,
    email TEXT NOT NULL,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL,
    last_login_at TEXT NOT NULL
);

-- enforcement has no default on purpose: the caller decides (new projects observe,
-- the migrated demo project enforce; decision 6).
CREATE TABLE project (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    retention_days INTEGER NOT NULL DEFAULT 90 CHECK (retention_days > 0),
    enforcement TEXT NOT NULL CHECK (enforcement IN ('observe', 'enforce')),
    ai_enabled INTEGER NOT NULL DEFAULT 1 CHECK (ai_enabled IN (0, 1)),
    webhook_url TEXT,
    webhook_secret_enc TEXT,
    created_at TEXT NOT NULL,
    deleted_at TEXT
);

CREATE TABLE membership (
    project_id TEXT NOT NULL REFERENCES project (id),
    person_id TEXT NOT NULL REFERENCES person (id),
    role TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'viewer')),
    notify_email INTEGER NOT NULL DEFAULT 1 CHECK (notify_email IN (0, 1)),
    created_at TEXT NOT NULL,
    PRIMARY KEY (project_id, person_id)
);

CREATE INDEX membership_by_person ON membership (person_id);

CREATE TABLE invitation (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES project (id),
    email TEXT NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'viewer')),
    invited_by TEXT NOT NULL REFERENCES person (id),
    created_at TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    accepted_at TEXT,
    revoked_at TEXT
);

CREATE INDEX invitation_by_email ON invitation (email);

-- Only the SHA-256 of the key is stored; prefix lets a person tell keys apart.
-- No expiry and no cap on active keys (decision 11).
CREATE TABLE api_key (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES project (id),
    name TEXT NOT NULL,
    prefix TEXT NOT NULL,
    key_hash TEXT NOT NULL UNIQUE,
    scope TEXT NOT NULL CHECK (scope IN ('sdk')),
    created_by TEXT NOT NULL,
    created_at TEXT NOT NULL,
    last_used_at TEXT,
    revoked_at TEXT
);

CREATE INDEX api_key_by_project ON api_key (project_id);

-- Append-only. A target of type 'user' always stores the hashed user_id (decision 12).
CREATE TABLE audit_log (
    seq INTEGER PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES project (id),
    actor_person_id TEXT REFERENCES person (id),
    actor_kind TEXT NOT NULL CHECK (actor_kind IN ('person', 'system')),
    action TEXT NOT NULL,
    target_type TEXT,
    target_id TEXT,
    meta TEXT NOT NULL DEFAULT '{}',
    ts TEXT NOT NULL
);

CREATE INDEX audit_log_by_project ON audit_log (project_id, seq);
